//! Resumable experiment-design workflow fabric for Worldgen P08 F13-F16.
use std::collections::BTreeSet;
use super::laboratory_integration_copilot_support::{self,InstrumentCopilotRequest,InstrumentCopilotReceipt};
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.laboratory-integration-workflow-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct InstrumentWorkflowRequest{pub workflow_id:String,pub copilot:InstrumentCopilotRequest,pub stage_order:Vec<String>,pub completed_stage_order:Vec<String>,pub checkpoint_seq:u64,pub budget_units:u64,pub compensation_enabled:bool,pub replay_identity:ContentHash}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct InstrumentWorkflowReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub workflow_id:String,pub disposition:String,pub stage_order:Vec<String>,pub completed_stage_order:Vec<String>,pub pending_stage_order:Vec<String>,pub compensation_order:Vec<String>,pub checkpoint_seq:u64,pub budget_units:u64,pub consumed_units:u64,pub replay_identity:ContentHash,pub copilot:InstrumentCopilotReceipt,pub workflow_digest:ContentHash,pub artifact:serde_json::Value,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum InstrumentWorkflowError{#[error("invalid laboratory integration workflow request: {0}")]Invalid(String),#[error("invalid laboratory integration workflow receipt: {0}")]Receipt(String),#[error("laboratory integration workflow artifact failed: {0}")]Artifact(String)}
fn h(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn o(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn s(v:&[String])->Vec<String>{let mut o=v.to_vec();o.sort();o.dedup();o}
impl InstrumentWorkflowReceipt{pub fn validate(&self)->Result<(),InstrumentWorkflowError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.workflow_id.trim().is_empty()||self.stage_order.is_empty()||self.checkpoint_seq==0||self.budget_units==0||self.consumed_units>self.budget_units||self.effect_receipts.is_empty()||![&self.replay_identity,&self.workflow_digest].into_iter().all(h){return Err(InstrumentWorkflowError::Receipt("laboratory integration workflow identity, stages, budget, locality, digests, or effects are incomplete".into()));}for v in [&self.stage_order,&self.completed_stage_order,&self.pending_stage_order,&self.compensation_order,&self.effect_receipts]{if !o(v){return Err(InstrumentWorkflowError::Receipt("laboratory integration workflow vectors are not canonical".into()));}}let stages=self.stage_order.iter().cloned().collect::<BTreeSet<_>>();let parts=self.completed_stage_order.iter().chain(&self.pending_stage_order).cloned().collect::<Vec<_>>();if stages.len()!=self.stage_order.len()||parts.len()!=stages.len()||parts.iter().cloned().collect::<BTreeSet<_>>()!=stages{return Err(InstrumentWorkflowError::Receipt("laboratory integration workflow stages do not partition".into()));}if self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.workflow_digest.as_str()){return Err(InstrumentWorkflowError::Receipt("laboratory integration workflow artifact digest is inconsistent".into()));}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,input_schema:&str,scale:&str,autonomy:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["laboratory_integration steward","workflow operator","downstream laboratory_integration consumer"],"behavior":format!("orchestrate resumable laboratory_integration control for {scale}"),"value":"makes laboratory_integration qualification restartable, budgeted, compensating, and replayable without hidden effects","input_schema":input_schema,"output_schema":"InstrumentWorkflowReceipt1@1","effects":["schedule:worldgen-laboratory-integration-workflow","block:unsafe-release"],"permissions":["schedule:bounded-laboratory-integration-workflow"],"determinism":"byte_stable","autonomy_tier":autonomy,"boundary":PRECLINICAL_BOUNDARY,"contract_version":version})}
pub fn schedule(request:&InstrumentWorkflowRequest,feature_id:&str,version:&str,scale:&str,require_approval:bool,require_federation:bool)->Result<InstrumentWorkflowReceipt,InstrumentWorkflowError>{if request.workflow_id.trim().is_empty()||request.stage_order.is_empty()||request.stage_order!=s(&request.stage_order)||request.checkpoint_seq==0||request.budget_units==0||!request.compensation_enabled||!h(&request.replay_identity)||request.copilot.instrument_request.replay_identity!=request.replay_identity{return Err(InstrumentWorkflowError::Invalid("laboratory integration workflow identity, stages, checkpoint, budget, compensation, or replay is invalid".into()));}let completed=request.completed_stage_order.iter().cloned().collect::<BTreeSet<_>>();if completed.iter().any(|x|!request.stage_order.contains(x)){return Err(InstrumentWorkflowError::Invalid("laboratory integration workflow completed stage is undeclared".into()));}let copilot=laboratory_integration_copilot_support::run(&request.copilot,feature_id,version,scale,require_approval,require_federation).map_err(|e|InstrumentWorkflowError::Invalid(e.to_string()))?;let pending=request.stage_order.iter().filter(|x|!completed.contains(*x)).cloned().collect::<Vec<_>>();let consumed=(request.copilot.action_order.len()as u64).min(request.budget_units);let mut comp=Vec::new();if copilot.disposition=="blocked"||request.copilot.action_order.len()as u64>request.budget_units{comp.push(format!("workflow:{}:retain-partial-laboratory_integration-verdict",request.workflow_id));}let disposition=if copilot.disposition=="blocked"||!comp.is_empty(){"blocked"}else if pending.is_empty(){"qualified"}else{"partial"};let effects=if disposition=="qualified"{vec![format!("schedule:worldgen-laboratory-integration-workflow:{}",request.workflow_id)]}else{vec!["block:unsafe-release".into()]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"workflow_id":request.workflow_id,"disposition":disposition,"stage_order":request.stage_order,"completed_stage_order":completed,"pending_stage_order":pending,"compensation_order":comp,"checkpoint_seq":request.checkpoint_seq,"budget_units":request.budget_units,"consumed_units":consumed,"replay_identity":request.replay_identity,"copilot":copilot.clone(),"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|InstrumentWorkflowError::Artifact(e.to_string()))?;let comp_order=s(&payload["compensation_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect::<Vec<_>>());let r=InstrumentWorkflowReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),workflow_id:request.workflow_id.clone(),disposition:disposition.into(),stage_order:request.stage_order.clone(),completed_stage_order:s(&request.completed_stage_order),pending_stage_order:pending,compensation_order:comp_order,checkpoint_seq:request.checkpoint_seq,budget_units:request.budget_units,consumed_units:consumed,replay_identity:request.replay_identity.clone(),copilot,workflow_digest:d.clone(),artifact:json!({"artifact_id":format!("laboratory-integration-workflow:{}",request.workflow_id),"content_type":CONTENT_TYPE,"content_hash":d,"boundary":PRECLINICAL_BOUNDARY}),effect_receipts:s(&effects),raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};r.validate()?;Ok(r)}






